/**
 * Release artifact availability for the Case Study download section.
 *
 * The JSON sibling is regenerated by the release scripts
 * (scripts/generate-case-study.mjs, scripts/package-demo.mjs) with real
 * file sizes once the artifacts exist. The ZIP download is intentionally
 * disabled inside the offline demo package build (VITE_OFFLINE_PACKAGE=1),
 * because the offline package cannot contain a copy of itself; the PDF
 * remains available there.
 */
import artifacts from './release-artifacts.json';

const offlinePackage = import.meta.env.VITE_OFFLINE_PACKAGE === '1';

export interface ReleaseArtifactInfo {
  fileName: string;
  available: boolean;
  sizeBytes: number;
}

export const RELEASE_ARTIFACTS: {
  pdf: ReleaseArtifactInfo;
  zip: ReleaseArtifactInfo;
  screenshots: { available: boolean };
} = {
  pdf: {
    fileName: artifacts.pdf.fileName,
    available: artifacts.pdf.available,
    sizeBytes: artifacts.pdf.sizeBytes,
  },
  zip: {
    fileName: artifacts.zip.fileName,
    available: artifacts.zip.available && !offlinePackage,
    sizeBytes: artifacts.zip.sizeBytes,
  },
  screenshots: {
    available: artifacts.screenshots.available,
  },
};
